"""
Intent catalog — 55–70+ topics per business vertical for V1 training.

Each intent becomes ~150 patterns via pattern_engine.expand_patterns().
"""
from __future__ import annotations

# ─── Shared seeds (imported by build_all_datasets) ───────────────────────────

GREETING_SEEDS = [
    "hello", "hi", "hey", "good morning", "good afternoon", "good evening",
    "greetings", "howdy", "hi there", "hello there", "start chat", "need help",
    "can you help", "i have a question", "looking for help", "customer service",
    "support chat", "talk to assistant", "website chat", "anyone there",
]
GOODBYE_SEEDS = [
    "bye", "goodbye", "see you", "thanks bye", "exit", "end chat",
    "done", "thats all", "no more questions", "have a good day", "take care",
    "signing off", "close chat", "quit", "later", "catch you later",
]
THANKS_SEEDS = [
    "thank you", "thanks", "thx", "much appreciated", "appreciate it",
    "that helps", "very helpful", "perfect thanks", "got it thanks",
    "you rock", "great answer", "awesome thanks", "cheers",
]
NAME_SEEDS = [
    "what is your name", "who are you", "are you a bot", "are you ai",
    "what can you do", "introduce yourself", "virtual assistant", "chatbot name",
]
SET_NAME_SEEDS = [
    "my name is", "call me", "i am called", "you can call me", "remember my name",
    "this is", "im", "nickname is",
]
STATUS_SEEDS = [
    "how are you", "how are you doing", "you ok", "hows it going",
    "how have you been", "everything ok", "hope you are well",
]
CONTACT_SEEDS = [
    "contact", "contact us", "phone number", "email address", "reach support",
    "customer support", "talk to someone", "live agent", "help desk",
    "get in touch", "support email", "support phone", "open a ticket",
]
HOURS_SEEDS = [
    "opening hours", "business hours", "what time open", "what time close",
    "when are you open", "weekend hours", "holiday hours", "open today",
    "closed today", "hours of operation",
]


def _t(tag: str, seeds: list[str], *responses: str) -> dict:
    return {
        "tag": tag,
        "seeds": seeds,
        "responses": list(responses) or ["I can help with that — contact our team for specifics."],
    }


def core_intents() -> list[dict]:
    return [
        _t("greeting", GREETING_SEEDS, "Hello{name}! How can I help you today?", "Hi there! What can I do for you?"),
        _t("status", STATUS_SEEDS, "I'm doing great, thanks! How can I help?", "All good — ready to answer your questions."),
        _t("thanks", THANKS_SEEDS, "You're welcome! Anything else?", "Happy to help — ask anytime."),
        _t("goodbye", GOODBYE_SEEDS, "Goodbye{name}! Have a wonderful day.", "Thanks for chatting. Take care!"),
        _t("name", NAME_SEEDS, "I'm your website assistant.", "I'm an AI helper trained on this business."),
        _t("set_name", SET_NAME_SEEDS, "Nice to meet you, {name}!", "Got it — I'll remember you as {name}."),
        _t("contact", CONTACT_SEEDS, "Email support or use our contact form — we reply within 24 hours.", "Reach us via the Contact page or live chat."),
        _t("hours", HOURS_SEEDS, "We're open Monday–Friday, 9 AM–6 PM.", "Standard hours: 9 AM–6 PM weekdays."),
    ]


